pub mod model_banks {include!("diagnostics.rs");}
include!("types.rs");
#[test] fn all_traces_preserve_legacy_summary(){use model_banks::ModelBankDiagnostics as D; let traces=[None,Some(D::default()),Some(D{geometry_candidates:7,pixel_geometry_refusals:7,pixel_rejections:0}),Some(D{geometry_candidates:7,pixel_geometry_refusals:0,pixel_rejections:7})];let mut count=0;for a in [None,Some(false),Some(true)]{for b in [None,Some(false),Some(true)]{for am in [false,true]{for bm in [false,true]{for at in traces {for bt in traces {let make=|support,model_attempted,model_diagnostics|NativeBankRecoveryTrace{support,model_attempted,model_diagnostics,native_miss:Some(SearchStageMiss::Native{recipes:3,candidates:5}),opposite_insufficient:Some(true),model_attempts:Some(25)};let e=NativeBankConsensusTraceEvidence{forward:make(a,am,at),reverse:make(b,bm,bt)};let legacy=NativeBankConsensusEvidence{forward:NativeBankDirectionSummary{support:a,model_attempted:am},reverse:NativeBankDirectionSummary{support:b,model_attempted:bm}};assert_eq!(e.supported(),legacy.supported());assert_eq!(e.summary().forward.support,a);assert_eq!(e.summary().reverse.model_attempted,bm);assert_eq!(e.forward.model_diagnostics,at);assert_eq!(e.reverse.model_diagnostics,bt);count+=1;}}}}}}assert_eq!(count,576);}
#[test] fn trace_is_compact_without_managed_bank_ownership(){assert!(!std::mem::needs_drop::<NativeBankConsensusTraceEvidence>());assert!(std::mem::size_of::<NativeBankConsensusTraceEvidence>()<=512);println!("trace_bytes={}",std::mem::size_of::<NativeBankConsensusTraceEvidence>());}
